// This is a simple interface which specifies echo.Route addition functions which
// are present on both echo.Echo and echo.Group, since we want to allow using
// either of them for path registration
type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithBaseURL(router, si, "")
}

// Registers handlers, and prepends BaseURL to the paths, so that the paths
// can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.POST(baseURL+"/auth/check-permissions", wrapper.CheckPermissions)
	router.POST(baseURL+"/auth/device", wrapper.RequestDeviceLogin)
	router.POST(baseURL+"/auth/login", wrapper.LoginSession)
	router.POST(baseURL+"/auth/logout", wrapper.LogoutSession)
	router.POST(baseURL+"/auth/register", wrapper.RegisterUser)
	router.GET(baseURL+"/auth/sso/callback", wrapper.GetSsoCallback)
	router.POST(baseURL+"/auth/sso/login", wrapper.RequestSsoLogin)
	router.GET(baseURL+"/current-user", wrapper.GetCurrentUser)
	router.GET(baseURL+"/devicelogins/:code", wrapper.GetDeviceLoginRequest)
	router.POST(baseURL+"/devicelogins/:requestId/actions/accept", wrapper.AcceptDeviceLoginRequest)
	router.POST(baseURL+"/devicelogins/:requestId/actions/poll", wrapper.PollDeviceLoginRequest)
	router.POST(baseURL+"/devicelogins/:requestId/actions/reject", wrapper.RejectDeviceLoginRequest)
	router.POST(baseURL+"/internal/authenticate", wrapper.InternalAuthenticate)
	router.POST(baseURL+"/internal/authorize", wrapper.InternalAuthorize)
	router.POST(baseURL+"/internal/orgs/:orgId/actions/remove-access", wrapper.InternalRemoveAccessFromOrg)
	router.POST(baseURL+"/internal/orgs/:orgId/actions/sync-scopes", wrapper.InternalSyncOrgScopes)
	router.POST(baseURL+"/internal/orgs/:orgId/actions/sync-spicedb", wrapper.InternalSyncOrgToSpiceDB)
	router.POST(baseURL+"/internal/orgs/:orgId/memberships", wrapper.InternalCreateOrgMembership)
	router.GET(baseURL+"/internal/orgs/:orgId/sso-configuration", wrapper.InternalGetSsoConfiguration)
	router.PUT(baseURL+"/internal/orgs/:orgId/sso-configuration", wrapper.InternalUpdateSsoConfiguration)
	router.GET(baseURL+"/orgs/:orgId/invitations", wrapper.ListInvitations)
	router.POST(baseURL+"/orgs/:orgId/invitations", wrapper.CreateInvitation)
	router.DELETE(baseURL+"/orgs/:orgId/invitations/:invitationId", wrapper.RevokeInvitation)
	router.GET(baseURL+"/orgs/:orgId/invitations/:invitationId", wrapper.GetInvitation)
	router.POST(baseURL+"/orgs/:orgId/invitations/:invitationId/actions/redeem", wrapper.RedeemInvitation)
	router.GET(baseURL+"/orgs/:orgId/members", wrapper.ListMembers)
	router.GET(baseURL+"/orgs/:orgId/memberships", wrapper.ListOrgMemberships)
	router.DELETE(baseURL+"/orgs/:orgId/memberships/:membershipId", wrapper.DeleteOrgMembership)
	router.GET(baseURL+"/orgs/:orgId/projects/:projectId/envs/:envId/users", wrapper.ListEnvironmentUsers)
	router.GET(baseURL+"/orgs/:orgId/projects/:projectId/users", wrapper.ListProjectUsers)
	router.GET(baseURL+"/orgs/:orgId/roles", wrapper.ListRoles)
	router.GET(baseURL+"/orgs/:orgId/roles/:roleId", wrapper.GetRole)
	router.GET(baseURL+"/orgs/:orgId/service-users", wrapper.ListServiceUsers)
	router.POST(baseURL+"/orgs/:orgId/service-users", wrapper.CreateServiceUser)
	router.DELETE(baseURL+"/orgs/:orgId/service-users/:serviceUserId", wrapper.DeleteServiceUser)
	router.PUT(baseURL+"/orgs/:orgId/service-users/:serviceUserId", wrapper.ReplaceServiceUserRoles)
	router.POST(baseURL+"/orgs/:orgId/service-users/:serviceUserId/actions/regenerate", wrapper.RegenerateServiceUser)
	router.PUT(baseURL+"/orgs/:orgId/users/:userId/memberships", wrapper.ReplaceOrgUserMemberships)
	router.POST(baseURL+"/users/:userId/actions/dismiss-prompt", wrapper.DismissPrompt)
	router.GET(baseURL+"/users/:userId/memberships", wrapper.ListUserMemberships)
	router.GET(baseURL+"/users/:userId/session-tokens", wrapper.ListUserSessionTokens)
	router.DELETE(baseURL+"/users/:userId/session-tokens/:hash", wrapper.RevokeUserSessionToken)

}

