// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Bulkly check permissions for the current subject that is logged in. This works for both human users and service users.
	// (POST /auth/check-permissions)
	CheckPermissions(ctx context.Context, request CheckPermissionsRequestObject) (CheckPermissionsResponseObject, error)
	// Begin a device login flow
	// (POST /auth/device)
	RequestDeviceLogin(ctx context.Context, request RequestDeviceLoginRequestObject) (RequestDeviceLoginResponseObject, error)
	// Log in and create a new session token
	// (POST /auth/login)
	LoginSession(ctx context.Context, request LoginSessionRequestObject) (LoginSessionResponseObject, error)
	// Log out the current session token
	// (POST /auth/logout)
	LogoutSession(ctx context.Context, request LogoutSessionRequestObject) (LogoutSessionResponseObject, error)
	// Register a new user using a login provider and grant an initial session token in the cookie.
	// (POST /auth/register)
	RegisterUser(ctx context.Context, request RegisterUserRequestObject) (RegisterUserResponseObject, error)
	// Callback SSO login flow
	// (GET /auth/sso/callback)
	GetSsoCallback(ctx context.Context, request GetSsoCallbackRequestObject) (GetSsoCallbackResponseObject, error)
	// Begin SSO login flow
	// (POST /auth/sso/login)
	RequestSsoLogin(ctx context.Context, request RequestSsoLoginRequestObject) (RequestSsoLoginResponseObject, error)
	// Get details of the current user that is logged in
	// (GET /current-user)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// View the attributes of a device login request
	// (GET /devicelogins/{code})
	GetDeviceLoginRequest(ctx context.Context, request GetDeviceLoginRequestRequestObject) (GetDeviceLoginRequestResponseObject, error)
	// Accept the device login request and allocate it a session token.
	// (POST /devicelogins/{requestId}/actions/accept)
	AcceptDeviceLoginRequest(ctx context.Context, request AcceptDeviceLoginRequestRequestObject) (AcceptDeviceLoginRequestResponseObject, error)
	// Poll the device login request and attempt to redeem for a session token
	// (POST /devicelogins/{requestId}/actions/poll)
	PollDeviceLoginRequest(ctx context.Context, request PollDeviceLoginRequestRequestObject) (PollDeviceLoginRequestResponseObject, error)
	// Reject the device login request
	// (POST /devicelogins/{requestId}/actions/reject)
	RejectDeviceLoginRequest(ctx context.Context, request RejectDeviceLoginRequestRequestObject) (RejectDeviceLoginRequestResponseObject, error)
	// Authenticate the current request and return From and Hash headers to the gateway
	// (POST /internal/authenticate)
	InternalAuthenticate(ctx context.Context, request InternalAuthenticateRequestObject) (InternalAuthenticateResponseObject, error)
	// Perform a policy enforcement check on the requested user, subjects, and permissions
	// (POST /internal/authorize)
	InternalAuthorize(ctx context.Context, request InternalAuthorizeRequestObject) (InternalAuthorizeResponseObject, error)
	// Removes all user and service user access from an org.
	// (POST /internal/orgs/{orgId}/actions/remove-access)
	InternalRemoveAccessFromOrg(ctx context.Context, request InternalRemoveAccessFromOrgRequestObject) (InternalRemoveAccessFromOrgResponseObject, error)
	// Sync scoped roles for all projects in an organization
	// (POST /internal/orgs/{orgId}/actions/sync-scopes)
	InternalSyncOrgScopes(ctx context.Context, request InternalSyncOrgScopesRequestObject) (InternalSyncOrgScopesResponseObject, error)
	// Sync organization relationships to SpiceDB
	// (POST /internal/orgs/{orgId}/actions/sync-spicedb)
	InternalSyncOrgToSpiceDB(ctx context.Context, request InternalSyncOrgToSpiceDBRequestObject) (InternalSyncOrgToSpiceDBResponseObject, error)
	// Manually create an org membership
	// (POST /internal/orgs/{orgId}/memberships)
	InternalCreateOrgMembership(ctx context.Context, request InternalCreateOrgMembershipRequestObject) (InternalCreateOrgMembershipResponseObject, error)
	// Get SSO configuration for the organization
	// (GET /internal/orgs/{orgId}/sso-configuration)
	InternalGetSsoConfiguration(ctx context.Context, request InternalGetSsoConfigurationRequestObject) (InternalGetSsoConfigurationResponseObject, error)
	// Update SSO configuration for the organization
	// (PUT /internal/orgs/{orgId}/sso-configuration)
	InternalUpdateSsoConfiguration(ctx context.Context, request InternalUpdateSsoConfigurationRequestObject) (InternalUpdateSsoConfigurationResponseObject, error)
	// List the invitations that are pending in the organization.
	// (GET /orgs/{orgId}/invitations)
	ListInvitations(ctx context.Context, request ListInvitationsRequestObject) (ListInvitationsResponseObject, error)
	// Create and send an email invitation to a user to join this organization.
	// (POST /orgs/{orgId}/invitations)
	CreateInvitation(ctx context.Context, request CreateInvitationRequestObject) (CreateInvitationResponseObject, error)
	// Deletes a pending invitation and invalidates it.
	// (DELETE /orgs/{orgId}/invitations/{invitationId})
	RevokeInvitation(ctx context.Context, request RevokeInvitationRequestObject) (RevokeInvitationResponseObject, error)
	// Previews an invitation for membership to an org without redeeming it. The user must be authorized or present the correct redemption token.
	// (GET /orgs/{orgId}/invitations/{invitationId})
	GetInvitation(ctx context.Context, request GetInvitationRequestObject) (GetInvitationResponseObject, error)
	// Redeems an invitation for membership to an org.
	// (POST /orgs/{orgId}/invitations/{invitationId}/actions/redeem)
	RedeemInvitation(ctx context.Context, request RedeemInvitationRequestObject) (RedeemInvitationResponseObject, error)
	// List the members of an org with their identity provider information
	// (GET /orgs/{orgId}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// List the memberships for an org
	// (GET /orgs/{orgId}/memberships)
	ListOrgMemberships(ctx context.Context, request ListOrgMembershipsRequestObject) (ListOrgMembershipsResponseObject, error)
	// Delete an org membership for a user. Due to internal caching, this may take up to a minute for authorized sessions to be revoked.
	// (DELETE /orgs/{orgId}/memberships/{membershipId})
	DeleteOrgMembership(ctx context.Context, request DeleteOrgMembershipRequestObject) (DeleteOrgMembershipResponseObject, error)
	// List the users and service users that have access to this environment.
	// (GET /orgs/{orgId}/projects/{projectId}/envs/{envId}/users)
	ListEnvironmentUsers(ctx context.Context, request ListEnvironmentUsersRequestObject) (ListEnvironmentUsersResponseObject, error)
	// List the users and service users that have access to this project.
	// (GET /orgs/{orgId}/projects/{projectId}/users)
	ListProjectUsers(ctx context.Context, request ListProjectUsersRequestObject) (ListProjectUsersResponseObject, error)
	// List the roles in this Organization.
	// (GET /orgs/{orgId}/roles)
	ListRoles(ctx context.Context, request ListRolesRequestObject) (ListRolesResponseObject, error)
	// Obtain details of a Role in an Organization.
	// (GET /orgs/{orgId}/roles/{roleId})
	GetRole(ctx context.Context, request GetRoleRequestObject) (GetRoleResponseObject, error)
	// List the service users in this org
	// (GET /orgs/{orgId}/service-users)
	ListServiceUsers(ctx context.Context, request ListServiceUsersRequestObject) (ListServiceUsersResponseObject, error)
	// Create a new service user in the org
	// (POST /orgs/{orgId}/service-users)
	CreateServiceUser(ctx context.Context, request CreateServiceUserRequestObject) (CreateServiceUserResponseObject, error)
	// Delete a service user from the org. Due to internal caching, this may take up to a minute for authorized sessions to be revoked.
	// (DELETE /orgs/{orgId}/service-users/{serviceUserId})
	DeleteServiceUser(ctx context.Context, request DeleteServiceUserRequestObject) (DeleteServiceUserResponseObject, error)
	// Replace all roles for a service user in an organization
	// (PUT /orgs/{orgId}/service-users/{serviceUserId})
	ReplaceServiceUserRoles(ctx context.Context, request ReplaceServiceUserRolesRequestObject) (ReplaceServiceUserRolesResponseObject, error)
	// Regenerate the service user token and extend the expiry. Due to internal caching, this may take up to a minute for authorized sessions to be revoked.
	// (POST /orgs/{orgId}/service-users/{serviceUserId}/actions/regenerate)
	RegenerateServiceUser(ctx context.Context, request RegenerateServiceUserRequestObject) (RegenerateServiceUserResponseObject, error)
	// Replace all memberships for a user in an organization
	// (PUT /orgs/{orgId}/users/{userId}/memberships)
	ReplaceOrgUserMemberships(ctx context.Context, request ReplaceOrgUserMembershipsRequestObject) (ReplaceOrgUserMembershipsResponseObject, error)
	// Dismiss a prompt for the user
	// (POST /users/{userId}/actions/dismiss-prompt)
	DismissPrompt(ctx context.Context, request DismissPromptRequestObject) (DismissPromptResponseObject, error)
	// List all of the memberships for the given user
	// (GET /users/{userId}/memberships)
	ListUserMemberships(ctx context.Context, request ListUserMembershipsRequestObject) (ListUserMembershipsResponseObject, error)
	// List all of the active user session tokens
	// (GET /users/{userId}/session-tokens)
	ListUserSessionTokens(ctx context.Context, request ListUserSessionTokensRequestObject) (ListUserSessionTokensResponseObject, error)
	// Revoke the session token for this user. Due to internal caching, this may take up to a minute for authorized sessions to be revoked.
	// (DELETE /users/{userId}/session-tokens/{hash})
	RevokeUserSessionToken(ctx context.Context, request RevokeUserSessionTokenRequestObject) (RevokeUserSessionTokenResponseObject, error)
}

type StrictHandlerFunc = strictecho.StrictEchoHandlerFunc
type StrictMiddlewareFunc = strictecho.StrictEchoMiddlewareFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

